begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(9);
insert into auth.users(id,email,email_confirmed_at) values ('00000000-0000-0000-0000-000000000031','a@example.invalid',now()),('00000000-0000-0000-0000-000000000032','c@example.invalid',now());
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000031',true);
set local role authenticated;
do $$begin perform set_config('test.house',public.create_household('Canales')::text,true);end$$;
do $$begin perform set_config('test.telegram',public.issue_telegram_nonce(current_setting('test.house')::uuid),true);end$$;
select throws_ok($$select public.consume_telegram_nonce(current_setting('test.telegram'),'123')$$,'42501',null,'usuario no vincula chat arbitrario');
select lives_ok($$select public.register_push_subscription(current_setting('test.house')::uuid,'{"endpoint":"https://fcm.googleapis.com/test","keys":{"p256dh":"BAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA","auth":"AAAAAAAAAAAAAAAAAAAAAA"}}')$$,'usuario registra dispositivo');
select throws_ok($$select public.register_push_subscription(current_setting('test.house')::uuid,'{"endpoint":"https://attacker.invalid/hook","keys":{"p256dh":"BAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA","auth":"AAAAAAAAAAAAAAAAAAAAAA"}}')$$,null,null,'endpoint externo desconocido rechazado');
select throws_ok($$select public.register_push_subscription(current_setting('test.house')::uuid,'{"endpoint":"https://fcm.googleapis.com/test","keys":{"p256dh":"x","auth":"y"}}')$$,null,null,'claves con longitud inválida rechazadas');
reset role;
set local role service_role;
select is(public.consume_telegram_nonce(current_setting('test.telegram'),'123'),true,'webhook validado consume nonce');
select is(public.consume_telegram_nonce(current_setting('test.telegram'),'123'),false,'nonce no se reutiliza');
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000032',true);
set local role authenticated;
select throws_ok($$select public.issue_telegram_nonce(current_setting('test.house')::uuid)$$,null,null,'no miembro no solicita enlace');
select throws_ok($$select public.register_push_subscription(current_setting('test.house')::uuid,'{"endpoint":"https://fcm.googleapis.com/other","keys":{"p256dh":"BAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA","auth":"AAAAAAAAAAAAAAAAAAAAAA"}}')$$,null,null,'no miembro no registra dispositivo');
do $$begin perform set_config('test.house_c',public.create_household('Otro')::text,true);end$$;
select throws_ok($$select public.register_push_subscription(current_setting('test.house_c')::uuid,'{"endpoint":"https://fcm.googleapis.com/test","keys":{"p256dh":"BAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA","auth":"AAAAAAAAAAAAAAAAAAAAAA"}}')$$,null,null,'otro usuario no secuestra endpoint');
reset role;
select * from finish();rollback;
